// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(address caller, bytes calldata data) public {
        vm.assume(caller != address(0));
        vm.assume(caller != c.Owner());
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        bool ok = true;
        try c.Command{value: 0}(address(0xdead), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
